// Normalize European Commission SEDIA (Funding & Tenders Portal) search
// results into the project's canonical call schema.
//
// The SEDIA search API is not officially documented. Field names below
// reflect the structure commonly observed on the public search endpoint
// and may need adjusting if the Commission changes the response shape --
// this node does NOT fail loudly on schema drift, unlike the HTML source
// below. That asymmetry is a known limitation, see README > Limitations.

const body = $input.first().json;
const results = body.results || body.data || [];

function metaValue(metadata, name) {
  const m = (metadata || []).find((x) => x.name === name);
  if (!m) return null;
  if (Array.isArray(m.values)) return m.values[0] ?? null;
  return m.value ?? null;
}

const out = [];
for (const r of results) {
  const meta = r.metadata || [];
  const externalId = r.reference || metaValue(meta, 'identifier') || String(r.id || '');
  if (!externalId) continue;

  const actionType = (metaValue(meta, 'actionType') || '').toLowerCase();
  const budgetRaw = metaValue(meta, 'budgetOverview') || metaValue(meta, 'callBudget');

  out.push({
    json: {
      source_code: 'ftop',
      external_id: externalId,
      title: r.title || metaValue(meta, 'title') || '',
      programme: metaValue(meta, 'programmePeriod') || metaValue(meta, 'frameworkProgramme') || 'Horizon Europe',
      type: actionType.includes('cascade') ? 'cascade' : 'grant',
      url: r.url || ('https://ec.europa.eu/info/funding-tenders/opportunities/portal/screen/opportunities/topic-details/' + externalId),
      summary: r.summary || metaValue(meta, 'abstract') || '',
      amount_min_eur: null,
      amount_max_eur: budgetRaw ? (Number(String(budgetRaw).replace(/[^\d.]/g, '')) || null) : null,
      deadline: metaValue(meta, 'deadlineDate') || metaValue(meta, 'startDate') || null,
      deadline_type: actionType.includes('multi') ? 'multiple' : 'single',
      topics: (metaValue(meta, 'topics') || '').toString().split(',').map((s) => s.trim()).filter(Boolean),
      raw_text: JSON.stringify(r),
      fetched_at: new Date().toISOString(),
    },
  });
}

return out;

// Normalize the Cascade Funding portal listing into the canonical call
// schema. HTML Extract returns one item holding parallel arrays (one
// entry per matched element); we zip them back into individual calls.
//
// Per the architecture doc's reliability rule: a source that suddenly
// returns zero elements almost always means its markup changed, not
// that there are genuinely no open calls -- fail loudly instead of
// silently reporting an empty result as "nothing to report".

const row = $input.first().json;
const titles = row.title || [];
const urls = row.url || [];
const deadlines = row.deadline_text || [];
const summaries = row.summary_text || [];

if (titles.length === 0) {
  throw new Error(
    'Cascade Funding: 0 items matched the .call-item selector. ' +
    'This almost certainly means the page markup changed, not that ' +
    'there are no open calls -- check and update the CSS selectors.'
  );
}

const out = [];
for (let i = 0; i < titles.length; i++) {
  const title = (titles[i] || '').trim();
  if (!title) continue;
  const url = urls[i] || '';
  out.push({
    json: {
      source_code: 'cascadefunding',
      external_id: (url.split('/').filter(Boolean).pop() || title).slice(0, 80),
      title,
      programme: 'Horizon Europe (Cascade / FSTP)',
      type: 'cascade',
      url,
      summary: (summaries[i] || '').trim(),
      amount_min_eur: null,
      amount_max_eur: null,
      deadline: (deadlines[i] || '').trim() || null,
      deadline_type: 'single',
      topics: [],
      raw_text: title + '\n' + (summaries[i] || '') + '\n' + (deadlines[i] || ''),
      fetched_at: new Date().toISOString(),
    },
  });
}

return out;

// Compute both dedup keys used later in the pipeline.
// Level 1 (per-source id) is hashed by the following Crypto node.
// Level 2 (cross-source key) catches the same opportunity published on
// more than one source. Level 3 from the architecture doc (embedding
// similarity) is a roadmap item, not implemented in this MVP.

return $input.all().map((item) => {
  const j = item.json;
  j.id_source_string = j.source_code + '::' + j.external_id;

  const normTitle = (j.title || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
  const amountBucket = j.amount_max_eur ? Math.round(j.amount_max_eur / 10000) * 10000 : 'na';
  j.cross_key = normTitle + '|' + (j.deadline || 'na') + '|' + amountBucket;

  return { json: j };
});

// Runs once per item. $json is this item's Information Extractor output
// (the extracted eligibility fields). $('Check Not Duplicate (L2)').item.json
// is the same call's canonical record from before the LLM step -- n8n's
// paired-item tracking keeps these aligned even though earlier nodes
// filtered some items out.

const extracted = $json.output || $json;
const call = $('Check Not Duplicate (L2)').item.json;
const rawText = call.raw_text || '';

const fieldPairs = [
  ['consortium_required', 'consortium_required_quote'],
  ['min_partners', 'min_partners_quote'],
  ['min_countries', 'min_countries_quote'],
  ['applicant_types', 'applicant_types_quote'],
  ['trl_min', 'trl_quote'],
  ['trl_max', 'trl_quote'],
  ['cofinancing_pct', 'cofinancing_pct_quote'],
];

const eligibility = {};
const droppedFields = [];
let checkedCount = 0;
let validCount = 0;

for (const [field, quoteField] of fieldPairs) {
  const value = extracted[field];
  if (value === undefined || value === null || value === '') continue;
  checkedCount += 1;
  const quote = extracted[quoteField];
  const quoteOk = typeof quote === 'string' && quote.length > 0 && rawText.includes(quote);
  if (quoteOk) {
    eligibility[field] = value;
    validCount += 1;
  } else {
    droppedFields.push(field);
  }
}

const extractionConfidence = checkedCount > 0 ? Math.round((validCount / checkedCount) * 100) / 100 : 0;

const canonicalFields = ['title', 'url', 'summary', 'deadline', 'amount_max_eur', 'programme'];
const filledCanonical = canonicalFields.filter((f) => call[f] !== null && call[f] !== undefined && call[f] !== '').length;
const completeness = Math.round((filledCanonical / canonicalFields.length) * 100) / 100;

return {
  json: Object.assign({}, call, {
    eligibility,
    dropped_fields: droppedFields,
    extraction_confidence: extractionConfidence,
    completeness,
    first_seen_at: new Date().toISOString(),
    last_seen_at: new Date().toISOString(),
    notified: false,
  }),
};

// Recipient profile drives filtering. In production this would be
// loaded from a Data Table row or one of the profiles/*.json files in
// this repo, so switching applicants doesn't touch the pipeline logic.
// Inlined here for MVP simplicity -- swap PROFILE or wire it up to a
// lookup if you need more than one recipient.

const PROFILE = {
  id: 'solo-software',
  countries: ['ES', 'UA', 'PL'],
  entity_types: ['sme', 'startup', 'natural_person'],
  consortium: false,
  max_partners: 2,
  trl: [3, 6],
  cofinancing_max_pct: 20,
  amount: [20000, 300000],
  deadline_min_days: 10,
  domains_include: ['ai', 'data', 'cybersecurity', 'digital', 'open-source'],
  domains_exclude: ['agriculture', 'construction', 'clinical-trials', 'maritime-hardware'],
};

const items = $input.all();
const evaluated = [];

for (const item of items) {
  const call = item.json;
  if (!call.id) continue; // alwaysOutputData empty-shell item when nothing pending

  const matched = [];
  const softFlags = [];
  const hardReasons = [];
  const e = call.eligibility || {};

  if (e.min_partners && e.min_partners > PROFILE.max_partners) {
    hardReasons.push('needs ' + e.min_partners + ' partners, profile allows ' + PROFILE.max_partners);
  } else {
    matched.push('consortium size');
  }

  if (call.deadline) {
    const days = (new Date(call.deadline) - new Date()) / 86400000;
    if (!Number.isNaN(days) && days < PROFILE.deadline_min_days) {
      hardReasons.push('deadline in ' + Math.max(0, Math.round(days)) + ' days, need ' + PROFILE.deadline_min_days + '+');
    } else {
      matched.push('deadline window');
    }
  }

  if (e.trl_min && e.trl_min > PROFILE.trl[1]) {
    softFlags.push('min TRL ' + e.trl_min + ' above profile max ' + PROFILE.trl[1]);
  } else if (e.trl_max && e.trl_max < PROFILE.trl[0]) {
    softFlags.push('max TRL ' + e.trl_max + ' below profile min ' + PROFILE.trl[0]);
  } else {
    matched.push('TRL range');
  }

  if (e.cofinancing_pct && e.cofinancing_pct > PROFILE.cofinancing_max_pct) {
    softFlags.push('co-financing ' + e.cofinancing_pct + '% above profile max ' + PROFILE.cofinancing_max_pct + '%');
  } else {
    matched.push('co-financing');
  }

  if (call.amount_max_eur && call.amount_max_eur < PROFILE.amount[0]) {
    softFlags.push('budget below profile minimum');
  } else {
    matched.push('budget range');
  }

  const topics = call.topics || [];
  if (topics.some((t) => PROFILE.domains_exclude.includes(t))) {
    hardReasons.push('topic in domains_exclude');
  } else if (topics.length && !topics.some((t) => PROFILE.domains_include.includes(t))) {
    softFlags.push('no overlap with domains_include');
  } else {
    matched.push('domain');
  }

  evaluated.push(Object.assign({}, call, {
    matched_conditions: matched,
    soft_flags: softFlags,
    hard_exclude: hardReasons.length > 0,
    hard_reasons: hardReasons,
  }));
}

const eligible = evaluated.filter((c) => !c.hard_exclude);
eligible.sort((a, b) => new Date(a.deadline || '9999-12-31') - new Date(b.deadline || '9999-12-31'));
const top = eligible.slice(0, 5);

return [{ json: { matched: top, matched_count: top.length, total_unnotified: items.length } }];

// Builds the Slack digest. An empty digest is a valid, expected result
// (architecture doc, section 8) -- it still gets sent as one line so
// silence is never ambiguous with "the workflow is broken".

const data = $input.first().json;
const matched = data.matched || [];

function formatAmount(min, max) {
  if (!min && !max) return 'amount not extracted';
  if (min && max) return '€' + min.toLocaleString() + '–€' + max.toLocaleString();
  return 'up to €' + (max || min).toLocaleString();
}

let text;
if (matched.length === 0) {
  text = '*EU Funding Radar* — ' + new Date().toISOString().slice(0, 10) + ': no new calls matched the profile today.';
} else {
  const lines = matched.map((c, i) => {
    const flags = (c.soft_flags || []).length ? ' _(check: ' + c.soft_flags.join('; ') + ')_' : '';
    return (i + 1) + '. *<' + c.url + '|' + c.title + '>* — ' + c.programme + '\n   Deadline: ' + (c.deadline || 'n/a') + ' · ' + formatAmount(c.amount_min_eur, c.amount_max_eur) + flags;
  });
  text = '*EU Funding Radar* — ' + matched.length + ' new call(s):\n\n' + lines.join('\n\n');
}

return [{ json: { digest_text: text } }];
